"use client";

import { useState, useEffect } from "react";
import axios from "axios";
import { AlertCircle, Loader2, UserCog, X } from "lucide-react";
import Layout from "../Layout"; // Adjust path to your Layout component

export default function DeputyDirectorReportsSuperAdmin() {
  const [reports, setReports] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState("");
  const [selectedReport, setSelectedReport] = useState(null);

  useEffect(() => {
    fetchReports();
  }, []);

  const fetchReports = async () => {
    setIsLoading(true);
    setError("");
    const token = localStorage.getItem("token");

    try {
      const response = await axios.get(`${process.env.REACT_APP_API_URL}/api/reports`, {
        headers: { Authorization: `Bearer ${token}`, Role: "superadmin" },
        params: { submitterRole: "deputydirector" }, // Backend filter
      });
      setReports(response.data.data || []);
    } catch (err) {
      setError("Erreur lors de la récupération des rapports : " + (err.response?.data?.message || err.message));
    } finally {
      setIsLoading(false);
    }
  };

  const openReportModal = (report) => setSelectedReport(report);
  const closeReportModal = () => setSelectedReport(null);

  return (
    <Layout>
      <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="bg-white rounded-2xl shadow-xl overflow-hidden border border-[#C8A45D/30]/50">
          {/* Header with improved gradient and spacing */}
          <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white p-6 flex items-center">
            <div className="bg-white/10 p-3 rounded-full mr-4">
              <UserCog className="h-8 w-8" />
            </div>
            <div>
              <h2 className="text-2xl font-bold tracking-tight">Rapports Gestionnaire d'hôtel</h2>
              <p className="text-white/80 mt-1 text-sm">Rapports soumis par les Gestionnaire d'hôtel</p>
            </div>
          </div>

          {error && (
            <div className="p-4 bg-red-50 border-l-4 border-red-500 flex items-center gap-3 m-4 rounded-r-md">
              <AlertCircle className="h-5 w-5 text-red-500 flex-shrink-0" />
              <p className="text-sm text-red-700">{error}</p>
            </div>
          )}

          <div className="p-6">
            {isLoading ? (
              <div className="flex justify-center items-center h-64">
                <div className="flex flex-col items-center gap-2">
                  <Loader2 className="h-10 w-10 text-[#00717F] animate-spin" />
                  <p className="text-[#00717F] text-sm font-medium">Chargement des rapports...</p>
                </div>
              </div>
            ) : reports.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-64 text-gray-500">
                <UserCog className="h-12 w-12 text-gray-300 mb-3" />
                <p className="text-center">Aucun rapport soumis par les Gestionnaire d'hôtel pour le moment.</p>
              </div>
            ) : (
              <ul className="space-y-4">
                {reports
                  .filter((report) => report.submitterRole === "Deputydirector") // Client-side filter
                  .map((report) => (
                    <li
                      key={report._id}
                      className="p-5 bg-gray-50 rounded-xl hover:bg-[#F5F6FA] transition-colors duration-150 cursor-pointer border border-transparent hover:border-[#C8A45D/30]/50 shadow-sm"
                      onClick={() => openReportModal(report)}
                    >
                      <div className="flex justify-between items-start">
                        <div className="flex-1">
                          <div className="flex items-center mb-2">
                            <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-blue-100 text-blue-800 mr-2">
                              {report.reportType }
                            </span>
                            <span className="text-xs text-gray-400">
                              {new Date(report.createdAt).toLocaleDateString("fr-FR")}
                            </span>
                          </div>
                          <p className="text-sm text-gray-700 mb-2">{report.description}</p>
                          <div className="flex items-center">
                            <div className="h-6 w-6 rounded-full bg-[#C8A45D] text-white flex items-center justify-center text-xs mr-2">
                              {report.deputyDirectorId?.name?.charAt(0) || "D"}
                            </div>
                            <p className="text-xs text-gray-500">
                              {report.deputyDirectorId ? report.deputyDirectorId.name : "Gestionnaire dhôtel inconnu"}
                            </p>
                          </div>
                        </div>
                        <div className="ml-4 flex-shrink-0">
                          <div className="h-8 w-8 rounded-full bg-[#F5F6FA] flex items-center justify-center">
                            <svg className="h-4 w-4 text-[#00717F]" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                            </svg>
                          </div>
                        </div>
                      </div>
                    </li>
                  ))}
              </ul>
            )}
          </div>
        </div>
      </div>

      {/* Modal for Report Details - Improved styling */}
      {selectedReport && (
        <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex justify-center items-center p-4">
          <div className="bg-white rounded-xl p-0 w-full max-w-md shadow-2xl animate-fadeIn overflow-hidden">
            <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white p-4 flex justify-between items-center">
              <h3 className="text-xl font-semibold">Détails du Rapport</h3>
              <button
                onClick={closeReportModal}
                className="rounded-full p-1 hover:bg-white/20 transition-colors"
              >
                <X className="h-5 w-5" />
              </button>
            </div>
            <div className="p-6 space-y-5">
              <div className="bg-blue-50 p-3 rounded-lg border border-blue-100">
                <p className="text-sm font-medium text-blue-800 mb-1">Type de Rapport</p>
                <p className="text-gray-900 font-medium">
                  {selectedReport.reportType }
                </p>
              </div>
              <div>
                <p className="text-sm font-medium text-gray-700 mb-1">Description</p>
                <p className="text-gray-900 bg-gray-50 p-3 rounded-lg border border-gray-100">{selectedReport.description}</p>
              </div>
              <div className="flex items-start space-x-3">
                <div className="h-10 w-10 rounded-full bg-[#C8A45D] text-white flex items-center justify-center text-sm flex-shrink-0">
                  {selectedReport.deputyDirectorId?.name?.charAt(0) || "D"}
                </div>
                <div>
                  <p className="text-sm font-medium text-gray-700">Soumis par</p>
                  <p className="text-gray-900">
                    {selectedReport.deputyDirectorId
                      ? `${selectedReport.deputyDirectorId.name} (${selectedReport.deputyDirectorId.email})`
                      : "Gestionnaire dhôtel inconnu"}
                  </p>
                </div>
              </div>
              <div>
                <p className="text-sm font-medium text-gray-700 mb-1">Date de Soumission</p>
                <p className="text-gray-900">{new Date(selectedReport.createdAt).toLocaleString("fr-FR")}</p>
              </div>
            </div>
            <div className="border-t border-gray-100 p-4 bg-gray-50 flex justify-end">
              <button
                onClick={closeReportModal}
                className="px-4 py-2 bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white rounded-md hover:bg-[#C8A45D] transition-colors duration-150 font-medium"
              >
                Fermer
              </button>
            </div>
          </div>
        </div>
      )}

      <style jsx global>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: scale(0.95); }
          to { opacity: 1; transform: scale(1); }
        }
        .animate-fadeIn {
          animation: fadeIn 0.2s ease-out forwards;
        }
      `}</style>
    </Layout>
  );
}
